from typing import Any, Callable


def run_jobs(jobs: list[dict], executor: Callable[[dict], Any]) -> list[dict]:
    """Run scheduled jobs sequentially according to their error policies."""
    run_log: list[dict] = []

    for job in jobs:
        policy = job["on_error"]["policy"]
        retries = job["on_error"]["retries"]
        attempts = 0
        succeeded = False

        max_attempts = retries + 1 if policy == "RETRY" else 1

        while attempts < max_attempts:
            attempts += 1
            try:
                executor(job)
            except Exception:
                if policy == "CONTINUE":
                    run_log.append(
                        {
                            "name": job["name"],
                            "attempts": attempts,
                            "outcome": "skip",
                            "audits": ["BATCH_ROWSKIP"],
                        }
                    )
                    break

                if policy == "RETRY" and attempts < max_attempts:
                    continue

                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": attempts,
                        "outcome": "abort",
                        "audits": [],
                    }
                )
                return run_log
            else:
                succeeded = True
                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": attempts,
                        "outcome": "ok",
                        "audits": [],
                    }
                )
                break

        if not succeeded and policy == "CONTINUE":
            continue

    return run_log
